1	/**
2	 * Página de Conferência & Recebimento — exclusiva para lojistas.
3	 *
4	 * Lista as requisições da loja do usuário logado. Para cada requisição:
5	 *  - Exibe progresso de conferência (itens conferidos/total)
6	 *  - Permite rastrear expedição via StoreExpeditionTracker
7	 *  - Permite conferir chegada via RequisicaoChegadaModal (com o fix anti-double-count)
8	 *
9	 * Filtro: requisicoes.loja_solicitante ilike '%{nome da loja}%'
10	 * Loja ativa: StoreContext → selectedStore
11	 */
12	import { useState } from "react";
13	import { useQuery } from "@tanstack/react-query";
14	import { Loader2, Package, PackageCheck, RefreshCw, ScanBarcode, Truck } from "lucide-react";
15	import { format } from "date-fns";
16	import { ptBR } from "date-fns/locale";
17	import { toast } from "sonner";
18	
19	import { MommaPageLayout } from "@/components/layout/MommaPageLayout";
20	import { Button } from "@/shared/ui/button";
21	import { cn } from "@/shared/lib/utils";
22	import { supabase } from "@/integrations/supabase/client";
23	import { useStore } from "@/shared/contexts/StoreContext";
24	import { normalizeRequisicaoStatus } from "@/shared/lib/logistics-utils";
25	
26	import { StoreExpeditionTracker } from "@/features/logistica/ui/StoreExpeditionTracker";
27	import { type ChegadaItem, RequisicaoChegadaModal } from "./RequisicaoChegadaModal";
28	
29	// ─── Tipos internos ────────────────────────────────────────────────────────────
30	
31	interface RequisicaoItemRaw {
32	  id: number;
33	  nome_produto: string;
34	  produto_master_id: number | null;
35	  quantidade_solicitada: number | null;
36	  quantidade_enviada: string | null;
37	  quantidade_recebida: string | null;
38	  recebida_via: string | null;
39	  recebida_at: string | null;
40	}
41	
42	interface RequisicaoRaw {
43	  id: number;
44	  nome: string;
45	  status: string;
46	  loja_solicitante: string;
47	  created_at: string;
48	  expedicao_id: string | null;
49	  chegada_concluida_at: string | null;
50	  requisicoes_itens: RequisicaoItemRaw[];
51	}
52	
53	interface ExpeditionState {
54	  expeditionId: string;
55	  storeName: string;
56	}
57	
58	// ─── Helpers ───────────────────────────────────────────────────────────────────
59	
60	function calcProgresso(items: RequisicaoItemRaw[]) {
61	  const total = items.length;
62	  const conferidos = items.filter(
63	    (i) => (Number(i.quantidade_recebida || 0) || 0) > 0,
64	  ).length;
65	  return { total, conferidos };
66	}
67	
68	function toChegadaItems(items: RequisicaoItemRaw[]): ChegadaItem[] {
69	  return items.map((item) => ({
70	    id: item.id,
71	    nome_produto: item.nome_produto,
72	    masterId: item.produto_master_id,
73	    quantidade_solicitada: item.quantidade_solicitada ?? 0,
74	    quantidade_enviada: String(item.quantidade_enviada ?? 0),
75	    quantidade_recebida: String(item.quantidade_recebida ?? 0),
76	    recebida_via: item.recebida_via as "bip" | "manual" | null,
77	    recebida_at: item.recebida_at,
78	  }));
79	}
80	
81	type BadgeStatus = "recebida" | "expedida" | "separando" | "aguardando";
82	
83	function resolverBadgeStatus(req: RequisicaoRaw): BadgeStatus {
84	  if (req.chegada_concluida_at) return "recebida";
85	  const norm = normalizeRequisicaoStatus(req.status);
86	  if (norm === "finalizada") return "expedida";
87	  if (norm === "em_progresso") return "separando";
88	  return "aguardando";
89	}
90	
91	function StatusBadge({ status }: { status: BadgeStatus }) {
92	  const map: Record<BadgeStatus, { label: string; className: string }> = {
93	    recebida: {
94	      label: "Recebida",
95	      className: "text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20",
96	    },
97	    expedida: {
98	      label: "Expedida",
99	      className: "text-blue-600 bg-blue-50 dark:bg-blue-900/20",
100	    },
101	    separando: {
102	      label: "Separando",
103	      className: "text-amber-600 bg-amber-50 dark:bg-amber-900/20",
104	    },
105	    aguardando: {
106	      label: "Aguardando",
107	      className: "text-gray-500 bg-gray-50 dark:bg-gray-900/20",
108	    },
109	  };
110	  const { label, className } = map[status];
111	  return (
112	    <span
113	      className={cn(
114	        "inline-block px-2 py-0.5 rounded-full text-[11px] font-semibold uppercase tracking-wider",
115	        className,
116	      )}
117	    >
118	      {label}
119	    </span>
120	  );
121	}
122	
123	// ─── Card de requisição ────────────────────────────────────────────────────────
124	
125	interface RequisicaoCardProps {
126	  req: RequisicaoRaw;
127	  onRastrear: () => void;
128	  onConferir: () => void;
129	}
130	
131	function RequisicaoCard({ req, onRastrear, onConferir }: RequisicaoCardProps) {
132	  const { total, conferidos } = calcProgresso(req.requisicoes_itens);
133	  const badgeStatus = resolverBadgeStatus(req);
134	  const pct = total > 0 ? Math.min(100, Math.round((conferidos / total) * 100)) : 0;
135	  const dataFormatada = format(new Date(req.created_at), "dd/MM/yyyy", { locale: ptBR });
136	  const temExpedicao = !!req.expedicao_id;
137	
138	  return (
139	    <div className="bg-white/60 dark:bg-black/20 backdrop-blur-md border border-white/30 dark:border-white/10 rounded-2xl p-4 shadow-sm hover:shadow-md transition-shadow">
140	      {/* Linha 1: nome + status */}
141	      <div className="flex items-start justify-between gap-2 mb-2">
142	        <h3 className="text-sm font-bold text-[#2D362E] dark:text-[#E6DCCF] leading-tight flex-1 min-w-0 truncate">
143	          {req.nome}
144	        </h3>
145	        <StatusBadge status={badgeStatus} />
146	      </div>
147	
148	      {/* Linha 2: data + progresso */}
149	      <div className="flex items-center justify-between gap-2 mb-2">
150	        <p className="text-[11px] text-muted-foreground">{dataFormatada}</p>
151	        {total > 0 && (
152	          <p className="text-[11px] text-muted-foreground tabular-nums">
153	            <span className={cn("font-semibold", conferidos === total ? "text-emerald-600" : "text-[#57715B]")}>
154	              {conferidos}
155	            </span>
156	            /{total} itens conferidos
157	          </p>
158	        )}
159	      </div>
160	
161	      {/* Linha 3: barra de progresso */}
162	      {total > 0 && (
163	        <div className="w-full h-1.5 bg-zinc-100 dark:bg-zinc-800 rounded-full overflow-hidden mb-3">
164	          <div
165	            className={cn(
166	              "h-full rounded-full transition-all duration-500",
167	              conferidos === total ? "bg-emerald-500" : "bg-[#57715B]",
168	            )}
169	            style={{ width: `${pct}%` }}
170	          />
171	        </div>
172	      )}
173	
174	      {/* Linha 4: botões de ação */}
175	      <div className="flex gap-2">
176	        <Button
177	          size="sm"
178	          variant="outline"
179	          disabled={!temExpedicao}
180	          title={temExpedicao ? "Rastrear expedição" : "Sem expedição vinculada"}
181	          onClick={onRastrear}
182	          className={cn(
183	            "h-9 gap-1.5 flex-1 text-[12px] border-[#57715B]/20",
184	            temExpedicao
185	              ? "hover:bg-[#57715B]/10 text-[#57715B]"
186	              : "opacity-50 cursor-not-allowed",
187	          )}
188	        >
189	          <Truck className="w-3.5 h-3.5" />
190	          Rastrear
191	        </Button>
192	        <Button
193	          size="sm"
194	          onClick={onConferir}
195	          className="h-9 gap-1.5 flex-1 text-[12px] bg-[#57715B] hover:bg-[#465b49] text-white"
196	        >
197	          <ScanBarcode className="w-3.5 h-3.5" />
198	          Conferir chegada
199	        </Button>
200	      </div>
201	    </div>
202	  );
203	}
204	
205	// ─── Página principal ──────────────────────────────────────────────────────────
206	
207	export function ConferenciaRecebimentoPage() {
208	  const { selectedStore } = useStore();
209	  const [expeditionOpen, setExpeditionOpen] = useState<ExpeditionState | null>(null);
210	  const [chegadaOpen, setChegadaOpen] = useState<RequisicaoRaw | null>(null);
211	
212	  const lojaLabel = selectedStore?.name ?? "";
213	
214	  const {
215	    data: requisicoes,
216	    isLoading,
217	    error,
218	    refetch,
219	  } = useQuery<RequisicaoRaw[]>({
220	    queryKey: ["conferencia-requisicoes", selectedStore?.id],
221	    queryFn: async () => {
222	      if (!lojaLabel) return [];
223	
224	      const { data, error: queryErr } = await supabase
225	        .from("requisicoes")
226	        .select(
227	          `id, nome, status, loja_solicitante, created_at, expedicao_id, chegada_concluida_at,
228	           requisicoes_itens (
229	             id, nome_produto, produto_master_id, quantidade_solicitada,
230	             quantidade_enviada, quantidade_recebida, recebida_via, recebida_at
231	           )`,
232	        )
233	        .ilike("loja_solicitante", `%${lojaLabel}%`)
234	        .order("created_at", { ascending: false })
235	        .limit(50);
236	
237	      if (queryErr) throw queryErr;
238	
239	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
240	      return (data ?? []) as any as RequisicaoRaw[];
241	    },
242	    enabled: !!selectedStore,
243	  });
244	
245	  const handleRefetch = () => {
246	    void refetch().catch(() => toast.error("Erro ao recarregar"));
247	  };
248	
249	  return (
250	    <MommaPageLayout>
251	      <div className="max-w-3xl mx-auto px-4 py-6">
252	        {/* Header */}
253	        <div className="flex items-center justify-between gap-3 mb-6">
254	          <div className="flex items-center gap-3">
255	            <div className="rounded-2xl bg-[#57715B]/10 p-3">
256	              <PackageCheck className="h-6 w-6 text-[#57715B]" />
257	            </div>
258	            <div>
259	              <h1 className="text-2xl md:text-3xl font-bold tracking-tight font-serif text-[#2D362E] dark:text-[#E6DCCF]">
260	                Conferência & Recebimento
261	              </h1>
262	              <p className="text-xs uppercase tracking-widest text-muted-foreground">
263	                Receba e confira entregas da fábrica
264	              </p>
265	            </div>
266	          </div>
267	          <Button
268	            variant="ghost"
269	            size="icon"
270	            onClick={handleRefetch}
271	            disabled={isLoading}
272	            className="rounded-2xl h-10 w-10 hover:bg-[#57715B]/10 text-[#57715B] flex-shrink-0"
273	            title="Recarregar"
274	          >
275	            <RefreshCw className={cn("w-4 h-4", isLoading && "animate-spin")} />
276	          </Button>
277	        </div>
278	
279	        {/* Estado de erro */}
280	        {error && (
281	          <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800/30 rounded-2xl p-4 mb-4 text-red-700 dark:text-red-400 text-sm">
282	            Erro ao carregar requisições. Tente recarregar.
283	          </div>
284	        )}
285	
286	        {/* Loading */}
287	        {isLoading && (
288	          <div className="flex flex-col items-center justify-center py-20 gap-3">
289	            <Loader2 className="w-8 h-8 text-[#57715B] animate-spin" />
290	            <p className="text-sm text-muted-foreground">Carregando requisições…</p>
291	          </div>
292	        )}
293	
294	        {/* Empty state */}
295	        {!isLoading && !error && (requisicoes?.length ?? 0) === 0 && (
296	          <div className="flex flex-col items-center justify-center py-20 gap-3">
297	            <div className="rounded-2xl bg-[#57715B]/10 p-5">
298	              <Package className="w-10 h-10 text-[#57715B]/60" />
299	            </div>
300	            <p className="text-base font-semibold text-[#2D362E] dark:text-[#E6DCCF]">
301	              Nenhuma requisição encontrada
302	            </p>
303	            <p className="text-sm text-muted-foreground text-center max-w-xs">
304	              Quando a fábrica preparar pedidos para esta loja, eles aparecerão aqui.
305	            </p>
306	          </div>
307	        )}
308	
309	        {/* Grid de cards */}
310	        {!isLoading && (requisicoes?.length ?? 0) > 0 && (
311	          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
312	            {(requisicoes ?? []).map((req) => (
313	              <RequisicaoCard
314	                key={req.id}
315	                req={req}
316	                onRastrear={() => {
317	                  if (!req.expedicao_id) return;
318	                  setExpeditionOpen({
319	                    expeditionId: req.expedicao_id,
320	                    storeName: selectedStore?.name ?? "",
321	                  });
322	                }}
323	                onConferir={() => setChegadaOpen(req)}
324	              />
325	            ))}
326	          </div>
327	        )}
328	      </div>
329	
330	      {/* Modal: Rastrear expedição */}
331	      {expeditionOpen && (
332	        <StoreExpeditionTracker
333	          isOpen
334	          onClose={() => setExpeditionOpen(null)}
335	          expeditionId={expeditionOpen.expeditionId}
336	          storeName={expeditionOpen.storeName}
337	        />
338	      )}
339	
340	      {/* Modal: Conferir chegada */}
341	      {chegadaOpen && (
342	        <RequisicaoChegadaModal
343	          isOpen
344	          onClose={() => setChegadaOpen(null)}
345	          requisicaoId={chegadaOpen.id}
346	          requisicaoNome={chegadaOpen.nome}
347	          lojaDestinoId={selectedStore?.id ?? 0}
348	          lojaDestinoNome={selectedStore?.name ?? ""}
349	          items={toChegadaItems(chegadaOpen.requisicoes_itens)}
350	          onConcluida={() => {
351	            void refetch();
352	            setChegadaOpen(null);
353	          }}
354	        />
355	      )}
356	    </MommaPageLayout>
357	  );
358	}
359	
360	export default ConferenciaRecebimentoPage;
361

