/**
 * Página de Conferência & Recebimento — exclusiva para lojistas.
 *
 * Lista as requisições da loja do usuário logado. Para cada requisição:
 *  - Exibe progresso de conferência (itens conferidos/total)
 *  - Permite rastrear expedição via StoreExpeditionTracker
 *  - Permite conferir chegada via RequisicaoChegadaModal (com o fix anti-double-count)
 *
 * Filtro: requisicoes.loja_solicitante ilike '%{nome da loja}%'
 * Loja ativa: StoreContext → selectedStore
 */
import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Loader2, Package, PackageCheck, RefreshCw, ScanBarcode, Truck } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { toast } from "sonner";

import { MommaPageLayout } from "@/components/layout/MommaPageLayout";
import { Button } from "@/shared/ui/button";
import { cn } from "@/shared/lib/utils";
import { supabase } from "@/integrations/supabase/client";
import { useStore } from "@/shared/contexts/StoreContext";
import { normalizeRequisicaoStatus } from "@/shared/lib/logistics-utils";

import { StoreExpeditionTracker } from "@/features/logistica/ui/StoreExpeditionTracker";
import { type ChegadaItem, RequisicaoChegadaModal } from "./RequisicaoChegadaModal";

// ─── Tipos internos ────────────────────────────────────────────────────────────

interface RequisicaoItemRaw {
  id: number;
  nome_produto: string;
  produto_master_id: number | null;
  quantidade_solicitada: number | null;
  quantidade_enviada: string | null;
  quantidade_recebida: string | null;
  recebida_via: string | null;
  recebida_at: string | null;
}

interface RequisicaoRaw {
  id: number;
  nome: string;
  status: string;
  loja_solicitante: string;
  created_at: string;
  expedicao_id: string | null;
  chegada_concluida_at: string | null;
  requisicoes_itens: RequisicaoItemRaw[];
}

interface ExpeditionState {
  expeditionId: string;
  storeName: string;
}

// ─── Helpers ───────────────────────────────────────────────────────────────────

function calcProgresso(items: RequisicaoItemRaw[]) {
  const total = items.length;
  const conferidos = items.filter(
    (i) => (Number(i.quantidade_recebida || 0) || 0) > 0,
  ).length;
  return { total, conferidos };
}

function toChegadaItems(items: RequisicaoItemRaw[]): ChegadaItem[] {
  return items.map((item) => ({
    id: item.id,
    nome_produto: item.nome_produto,
    masterId: item.produto_master_id,
    quantidade_solicitada: item.quantidade_solicitada ?? 0,
    quantidade_enviada: String(item.quantidade_enviada ?? 0),
    quantidade_recebida: String(item.quantidade_recebida ?? 0),
    recebida_via: item.recebida_via as "bip" | "manual" | null,
    recebida_at: item.recebida_at,
  }));
}

type BadgeStatus = "recebida" | "expedida" | "separando" | "aguardando";

function resolverBadgeStatus(req: RequisicaoRaw): BadgeStatus {
  if (req.chegada_concluida_at) return "recebida";
  const norm = normalizeRequisicaoStatus(req.status);
  if (norm === "finalizada") return "expedida";
  if (norm === "em_progresso") return "separando";
  return "aguardando";
}

function StatusBadge({ status }: { status: BadgeStatus }) {
  const map: Record<BadgeStatus, { label: string; className: string }> = {
    recebida: {
      label: "Recebida",
      className: "text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20",
    },
    expedida: {
      label: "Expedida",
      className: "text-blue-600 bg-blue-50 dark:bg-blue-900/20",
    },
    separando: {
      label: "Separando",
      className: "text-amber-600 bg-amber-50 dark:bg-amber-900/20",
    },
    aguardando: {
      label: "Aguardando",
      className: "text-gray-500 bg-gray-50 dark:bg-gray-900/20",
    },
  };
  const { label, className } = map[status];
  return (
    <span
      className={cn(
        "inline-block px-2 py-0.5 rounded-full text-[11px] font-semibold uppercase tracking-wider",
        className,
      )}
    >
      {label}
    </span>
  );
}

// ─── Card de requisição ────────────────────────────────────────────────────────

interface RequisicaoCardProps {
  req: RequisicaoRaw;
  onRastrear: () => void;
  onConferir: () => void;
}

function RequisicaoCard({ req, onRastrear, onConferir }: RequisicaoCardProps) {
  const { total, conferidos } = calcProgresso(req.requisicoes_itens);
  const badgeStatus = resolverBadgeStatus(req);
  const pct = total > 0 ? Math.min(100, Math.round((conferidos / total) * 100)) : 0;
  const dataFormatada = format(new Date(req.created_at), "dd/MM/yyyy", { locale: ptBR });
  const temExpedicao = !!req.expedicao_id;

  return (
    <div className="bg-white/60 dark:bg-black/20 backdrop-blur-md border border-white/30 dark:border-white/10 rounded-2xl p-4 shadow-sm hover:shadow-md transition-shadow">
      {/* Linha 1: nome + status */}
      <div className="flex items-start justify-between gap-2 mb-2">
        <h3 className="text-sm font-bold text-[#2D362E] dark:text-[#E6DCCF] leading-tight flex-1 min-w-0 truncate">
          {req.nome}
        </h3>
        <StatusBadge status={badgeStatus} />
      </div>

      {/* Linha 2: data + progresso */}
      <div className="flex items-center justify-between gap-2 mb-2">
        <p className="text-[11px] text-muted-foreground">{dataFormatada}</p>
        {total > 0 && (
          <p className="text-[11px] text-muted-foreground tabular-nums">
            <span className={cn("font-semibold", conferidos === total ? "text-emerald-600" : "text-[#57715B]")}>
              {conferidos}
            </span>
            /{total} itens conferidos
          </p>
        )}
      </div>

      {/* Linha 3: barra de progresso */}
      {total > 0 && (
        <div className="w-full h-1.5 bg-zinc-100 dark:bg-zinc-800 rounded-full overflow-hidden mb-3">
          <div
            className={cn(
              "h-full rounded-full transition-all duration-500",
              conferidos === total ? "bg-emerald-500" : "bg-[#57715B]",
            )}
            style={{ width: `${pct}%` }}
          />
        </div>
      )}

      {/* Linha 4: botões de ação */}
      <div className="flex gap-2">
        <Button
          size="sm"
          variant="outline"
          disabled={!temExpedicao}
          title={temExpedicao ? "Rastrear expedição" : "Sem expedição vinculada"}
          onClick={onRastrear}
          className={cn(
            "h-9 gap-1.5 flex-1 text-[12px] border-[#57715B]/20",
            temExpedicao
              ? "hover:bg-[#57715B]/10 text-[#57715B]"
              : "opacity-50 cursor-not-allowed",
          )}
        >
          <Truck className="w-3.5 h-3.5" />
          Rastrear
        </Button>
        <Button
          size="sm"
          onClick={onConferir}
          className="h-9 gap-1.5 flex-1 text-[12px] bg-[#57715B] hover:bg-[#465b49] text-white"
        >
          <ScanBarcode className="w-3.5 h-3.5" />
          Conferir chegada
        </Button>
      </div>
    </div>
  );
}

// ─── Página principal ──────────────────────────────────────────────────────────

export function ConferenciaRecebimentoPage() {
  const { selectedStore } = useStore();
  const [expeditionOpen, setExpeditionOpen] = useState<ExpeditionState | null>(null);
  const [chegadaOpen, setChegadaOpen] = useState<RequisicaoRaw | null>(null);

  const lojaLabel = selectedStore?.name ?? "";

  const {
    data: requisicoes,
    isLoading,
    error,
    refetch,
  } = useQuery<RequisicaoRaw[]>({
    queryKey: ["conferencia-requisicoes", selectedStore?.id],
    queryFn: async () => {
      if (!lojaLabel) return [];

      const { data, error: queryErr } = await supabase
        .from("requisicoes")
        .select(
          `id, nome, status, loja_solicitante, created_at, expedicao_id, chegada_concluida_at,
           requisicoes_itens (
             id, nome_produto, produto_master_id, quantidade_solicitada,
             quantidade_enviada, quantidade_recebida, recebida_via, recebida_at
           )`,
        )
        .ilike("loja_solicitante", `%${lojaLabel}%`)
        .order("created_at", { ascending: false })
        .limit(50);

      if (queryErr) throw queryErr;

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      return (data ?? []) as any as RequisicaoRaw[];
    },
    enabled: !!selectedStore,
  });

  const handleRefetch = () => {
    void refetch().catch(() => toast.error("Erro ao recarregar"));
  };

  return (
    <MommaPageLayout>
      <div className="max-w-3xl mx-auto px-4 py-6">
        {/* Header */}
        <div className="flex items-center justify-between gap-3 mb-6">
          <div className="flex items-center gap-3">
            <div className="rounded-2xl bg-[#57715B]/10 p-3">
              <PackageCheck className="h-6 w-6 text-[#57715B]" />
            </div>
            <div>
              <h1 className="text-2xl md:text-3xl font-bold tracking-tight font-serif text-[#2D362E] dark:text-[#E6DCCF]">
                Conferência & Recebimento
              </h1>
              <p className="text-xs uppercase tracking-widest text-muted-foreground">
                Receba e confira entregas da fábrica
              </p>
            </div>
          </div>
          <Button
            variant="ghost"
            size="icon"
            onClick={handleRefetch}
            disabled={isLoading}
            className="rounded-2xl h-10 w-10 hover:bg-[#57715B]/10 text-[#57715B] flex-shrink-0"
            title="Recarregar"
          >
            <RefreshCw className={cn("w-4 h-4", isLoading && "animate-spin")} />
          </Button>
        </div>

        {/* Estado de erro */}
        {error && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800/30 rounded-2xl p-4 mb-4 text-red-700 dark:text-red-400 text-sm">
            Erro ao carregar requisições. Tente recarregar.
          </div>
        )}

        {/* Loading */}
        {isLoading && (
          <div className="flex flex-col items-center justify-center py-20 gap-3">
            <Loader2 className="w-8 h-8 text-[#57715B] animate-spin" />
            <p className="text-sm text-muted-foreground">Carregando requisições…</p>
          </div>
        )}

        {/* Empty state */}
        {!isLoading && !error && (requisicoes?.length ?? 0) === 0 && (
          <div className="flex flex-col items-center justify-center py-20 gap-3">
            <div className="rounded-2xl bg-[#57715B]/10 p-5">
              <Package className="w-10 h-10 text-[#57715B]/60" />
            </div>
            <p className="text-base font-semibold text-[#2D362E] dark:text-[#E6DCCF]">
              Nenhuma requisição encontrada
            </p>
            <p className="text-sm text-muted-foreground text-center max-w-xs">
              Quando a fábrica preparar pedidos para esta loja, eles aparecerão aqui.
            </p>
          </div>
        )}

        {/* Grid de cards */}
        {!isLoading && (requisicoes?.length ?? 0) > 0 && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {(requisicoes ?? []).map((req) => (
              <RequisicaoCard
                key={req.id}
                req={req}
                onRastrear={() => {
                  if (!req.expedicao_id) return;
                  setExpeditionOpen({
                    expeditionId: req.expedicao_id,
                    storeName: selectedStore?.name ?? "",
                  });
                }}
                onConferir={() => setChegadaOpen(req)}
              />
            ))}
          </div>
        )}
      </div>

      {/* Modal: Rastrear expedição */}
      {expeditionOpen && (
        <StoreExpeditionTracker
          isOpen
          onClose={() => setExpeditionOpen(null)}
          expeditionId={expeditionOpen.expeditionId}
          storeName={expeditionOpen.storeName}
        />
      )}

      {/* Modal: Conferir chegada */}
      {chegadaOpen && (
        <RequisicaoChegadaModal
          isOpen
          onClose={() => setChegadaOpen(null)}
          requisicaoId={chegadaOpen.id}
          requisicaoNome={chegadaOpen.nome}
          lojaDestinoId={selectedStore?.id ?? 0}
          lojaDestinoNome={selectedStore?.name ?? ""}
          items={toChegadaItems(chegadaOpen.requisicoes_itens)}
          onConcluida={() => {
            void refetch();
            setChegadaOpen(null);
          }}
        />
      )}
    </MommaPageLayout>
  );
}

export default ConferenciaRecebimentoPage;

import { Lock, LogOut, User, ChevronsLeft, Moon, Sun, ChevronDown, Gauge } from "lucide-react";
import { NavLink } from "react-router-dom";
import { useIsMobile } from "@/shared/hooks/use-mobile";
import { useAuth } from "@/shared/hooks/useAuth";
import { useTheme } from "next-themes";
