1	/**
2	 * Modal de conferência de CHEGADA na loja (espelho da expedição).
3	 *
4	 * Quando o caminhão chega na loja destino, o operador entra com a requisição
5	 * carregada (apenas itens da requisição da própria loja). Para cada item:
6	 *  - Bipa o QR da caixa → RPC marcar_conferencia_requisicao(uid, requisicaoId, lojaId, meta)
7	 *    APENAS MARCAÇÃO — não mexe em estoque. Atualiza requisicoes_itens.quantidade_recebida.
8	 *  - OU marca manual (sem etiqueta): apenas atualiza recebida_via='manual'
9	 *    + quantidade_recebida = quantidade_solicitada (sem mexer em movimentacoes).
10	 *
11	 * Ao clicar "Finalizar e dar entrada": chama dar_entrada_requisicao(requisicaoId) UMA vez,
12	 * que gera as movimentacoes de estoque de todas as etiquetas bipadas (idempotente).
13	 *
14	 * Salva parcial. Operador pode fechar e voltar depois — state hidrata da DB.
15	 */
16	import { useEffect, useMemo, useRef, useState } from "react";
17	import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
18	import { Button } from "@/shared/ui/button";
19	import { Input } from "@/shared/ui/input";
20	import { ScrollArea } from "@/shared/ui/scroll-area";
21	import {
22	  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
23	  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
24	} from "@/shared/ui/alert-dialog";
25	import {
26	  ArrowLeft, Bluetooth, Camera, ScanBarcode, Package, MapPin, CheckCircle2,
27	  AlertTriangle, Hand, Boxes,
28	} from "lucide-react";
29	import { toast } from "sonner";
30	import { cn } from "@/shared/lib/utils";
31	import { supabase } from "@/integrations/supabase/client";
32	import {
33	  useEtiquetaScanner, playSuccessSound, playErrorSound, playWarningSound,
34	  type ScannedPayload,
35	} from "@/shared/hooks/useEtiquetaScanner";
36	import { CameraScannerStatus } from "@/features/logistica/ui/CameraScannerStatus";
37	
38	export interface ChegadaItem {
39	  id: number; // id em requisicoes_itens
40	  nome_produto: string;
41	  masterId: number | null;
42	  quantidade_solicitada: number;
43	  quantidade_enviada: string; // o que foi expedido pela fábrica
44	  quantidade_recebida: string; // estado persistido (parcial entre sessões)
45	  recebida_via: "bip" | "manual" | null;
46	  recebida_at: string | null;
47	}
48	
49	interface BipBuffer {
50	  itemId: number;
51	  uid: string;
52	  qty: number;
53	  embalagem: string | null;
54	  bipadoAt: number;
55	}
56	
57	interface ManualState {
58	  open: boolean;
59	  item?: ChegadaItem;
60	  quantidade: string;
61	}
62	
63	interface Props {
64	  isOpen: boolean;
65	  onClose: () => void;
66	  requisicaoId: number;
67	  requisicaoNome: string;
68	  lojaDestinoId: number;
69	  lojaDestinoNome: string;
70	  items: ChegadaItem[];
71	  /** Quando o operador clica em "Finalizar e dar entrada" — pai recarrega/atualiza UI. */
72	  onConcluida?: () => void;
73	}
74	
75	interface DarEntradaResult {
76	  ok: boolean;
77	  etiquetas_processadas: number;
78	  total_quantidade: number;
79	  ja_processadas: number;
80	  alertas: string[];
81	  error?: string;
82	}
83	
84	export function RequisicaoChegadaModal({
85	  isOpen, onClose, requisicaoId, requisicaoNome,
86	  lojaDestinoId, lojaDestinoNome, items, onConcluida,
87	}: Props) {
88	  const [localItems, setLocalItems] = useState<ChegadaItem[]>([]);
89	  const [bipsLog, setBipsLog] = useState<BipBuffer[]>([]);
90	  const uidsLidosRef = useRef<Set<string>>(new Set());
91	  const [manual, setManual] = useState<ManualState>({ open: false, quantidade: "" });
92	  const [concluindo, setConcluindo] = useState(false);
93	  const [confirmandoFinalizar, setConfirmandoFinalizar] = useState(false);
94	
95	  useEffect(() => {
96	    if (!isOpen) return;
97	    setLocalItems(items.map((i) => ({ ...i })));
98	    setBipsLog([]);
99	    uidsLidosRef.current = new Set();
100	  }, [isOpen, items]);
101	
102	  // Marca a flag de chegada_iniciada_at na primeira interação
103	  const marcarChegadaIniciada = async () => {
104	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
105	    await (supabase.from("requisicoes") as any)
106	      .update({ chegada_iniciada_at: new Date().toISOString() })
107	      .eq("id", requisicaoId)
108	      .is("chegada_iniciada_at", null);
109	  };
110	
111	  const updateItemRow = async (
112	    itemId: number,
113	    novaQtd: string,
114	    via: "bip" | "manual",
115	    userId: string | null,
116	  ) => {
117	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
118	    return (supabase.from("requisicoes_itens") as any)
119	      .update({
120	        quantidade_recebida: novaQtd,
121	        recebida_via: via,
122	        recebida_at: new Date().toISOString(),
123	        recebida_por: userId,
124	      })
125	      .eq("id", itemId);
126	  };
127	
128	  const handleBip = async (payload: ScannedPayload) => {
129	    if (!payload.uid) {
130	      playErrorSound();
131	      toast.error("Etiqueta sem UID — não rastreável");
132	      return;
133	    }
134	    if (uidsLidosRef.current.has(payload.uid)) {
135	      playErrorSound();
136	      toast.error("Caixa já bipada nesta chegada");
137	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
138	      return;
139	    }
140	
141	    await marcarChegadaIniciada();
142	
143	    // Buscar dados da etiqueta para saber produto e quantidade
144	    const { data: etiquetaData, error: etiquetaErr } = await supabase
145	      .from("etiquetas_qr")
146	      .select("quantidade_interna, produto_master_id, lote_id")
147	      .eq("uid", payload.uid)
148	      .maybeSingle();
149	
150	    if (etiquetaErr) {
151	      playErrorSound();
152	      toast.error(`Falha ao ler etiqueta: ${etiquetaErr.message}`);
153	      return;
154	    }
155	
156	    const qty = Number(etiquetaData?.quantidade_interna ?? payload.qty ?? 1);
157	    const masterId = etiquetaData?.produto_master_id ?? null;
158	    const loteId = (etiquetaData as { lote_id?: string | null } | null)?.lote_id ?? null;
159	
160	    // RPC de marcação de conferência (NÃO mexe em estoque — só registra o bip)
161	    // @ts-expect-error RPC nova ainda não regenerada nos tipos
162	    const { data: marcRes, error: marcErr } = await (supabase.rpc as any)(
163	      "marcar_conferencia_requisicao",
164	      {
165	        p_uid: payload.uid,
166	        p_requisicao_id: requisicaoId,
167	        p_loja_id: lojaDestinoId,
168	        p_meta: {
169	          quantidade_interna: qty,
170	          produto_master_id: masterId,
171	          lote_id: loteId,
172	        },
173	      },
174	    );
175	
176	    if (marcErr) {
177	      playErrorSound();
178	      toast.error(`Falha ao registrar conferência: ${marcErr.message}`);
179	      return;
180	    }
181	
182	    const marcResult = marcRes as { ok: boolean; erro?: string; alertas?: string[] } | null;
183	    if (!marcResult?.ok) {
184	      playErrorSound();
185	      toast.error(marcResult?.erro || "Erro ao registrar bip de conferência");
186	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
187	      return;
188	    }
189	
190	    (marcResult.alertas ?? []).forEach((a) => {
191	      playWarningSound();
192	      toast.warning(a);
193	    });
194	
195	    const target = localItems.find((i) => i.masterId === masterId);
196	    if (!target) {
197	      playWarningSound();
198	      if (navigator.vibrate) navigator.vibrate([100, 50, 100]);
199	      toast.warning(`Produto #${masterId} NÃO está nesta requisição`);
200	      uidsLidosRef.current.add(payload.uid);
201	      return;
202	    }
203	
204	    // Soma à quantidade_recebida atual
205	    const baseAtual = Number(target.quantidade_recebida || "0") || 0;
206	    const novaQtdNum = baseAtual + qty;
207	
208	    const { data: { user } } = await supabase.auth.getUser();
209	    const { error: upErr } = await updateItemRow(target.id, String(novaQtdNum), "bip", user?.id ?? null);
210	    if (upErr) {
211	      playErrorSound();
212	      toast.error(`Erro ao salvar conferência: ${upErr.message}`);
213	      return;
214	    }
215	
216	    playSuccessSound();
217	    if (navigator.vibrate) navigator.vibrate(80);
218	    toast.success(`${target.nome_produto} +${qty} un`);
219	
220	    setLocalItems((prev) =>
221	      prev.map((i) => i.id === target.id
222	        ? { ...i, quantidade_recebida: String(novaQtdNum), recebida_via: "bip", recebida_at: new Date().toISOString() }
223	        : i),
224	    );
225	    setBipsLog((prev) => [
226	      { itemId: target.id, uid: payload.uid, qty, embalagem: null, bipadoAt: Date.now() },
227	      ...prev,
228	    ]);
229	    uidsLidosRef.current.add(payload.uid);
230	  };
231	
232	  const scanner = useEtiquetaScanner({
233	    enabled: isOpen,
234	    onScan: handleBip,
235	    cameraElementId: "chegada-qr-reader",
236	    onInvalid: () => toast.error("QR ilegível"),
237	    onDuplicate: () => {
238	      playErrorSound();
239	      toast.error("Esta etiqueta já foi bipada");
240	    },
241	  });
242	
243	  const askManual = (item: ChegadaItem) => {
244	    const restante = Math.max(0, item.quantidade_solicitada - (Number(item.quantidade_recebida || "0") || 0));
245	    setManual({
246	      open: true,
247	      item,
248	      quantidade: String(restante > 0 ? restante : item.quantidade_solicitada),
249	    });
250	  };
251	
252	  const confirmManual = async () => {
253	    if (!manual.item) return;
254	    const qty = Number(manual.quantidade);
255	    if (!Number.isFinite(qty) || qty < 0) {
256	      toast.error("Quantidade inválida");
257	      return;
258	    }
259	    await marcarChegadaIniciada();
260	    const { data: { user } } = await supabase.auth.getUser();
261	    const { error } = await updateItemRow(manual.item.id, String(qty), "manual", user?.id ?? null);
262	    if (error) {
263	      toast.error(`Erro ao salvar: ${error.message}`);
264	      return;
265	    }
266	    setLocalItems((prev) =>
267	      prev.map((i) => i.id === manual.item!.id
268	        ? { ...i, quantidade_recebida: String(qty), recebida_via: "manual", recebida_at: new Date().toISOString() }
269	        : i),
270	    );
271	    setManual({ open: false, quantidade: "" });
272	    toast.success(`${manual.item.nome_produto}: ${qty} un (manual)`);
273	  };
274	
275	  const executarFinalizacao = async () => {
276	    setConcluindo(true);
277	    setConfirmandoFinalizar(false);
278	
279	    // Chamar dar_entrada_requisicao UMA vez — dá entrada no estoque de TODAS as etiquetas bipadas
280	    // @ts-expect-error RPC nova ainda não regenerada nos tipos
281	    const { data: entradaRes, error: entradaErr } = await (supabase.rpc as any)(
282	      "dar_entrada_requisicao",
283	      { p_requisicao_id: requisicaoId },
284	    );
285	
286	    if (entradaErr) {
287	      toast.error(`Erro ao dar entrada no estoque: ${entradaErr.message}`);
288	      setConcluindo(false);
289	      return;
290	    }
291	
292	    const resultado = entradaRes as DarEntradaResult | null;
293	    if (!resultado?.ok) {
294	      toast.error(resultado?.error || "Falha ao registrar entrada no estoque");
295	      setConcluindo(false);
296	      return;
297	    }
298	
299	    // Feedback de sucesso
300	    toast.success(
301	      `Entrada registrada: ${resultado.etiquetas_processadas} etiqueta(s), ${resultado.total_quantidade} unidade(s)`,
302	    );
303	
304	    if (resultado.ja_processadas > 0) {
305	      toast.info(`${resultado.ja_processadas} etiqueta(s) já haviam sido processadas anteriormente`);
306	    }
307	
308	    (resultado.alertas ?? []).forEach((a) => toast.warning(a));
309	
310	    // Marcar chegada como concluída no banco
311	    const { data: { user } } = await supabase.auth.getUser();
312	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
313	    await (supabase.from("requisicoes") as any)
314	      .update({
315	        chegada_concluida_at: new Date().toISOString(),
316	        chegada_concluida_por: user?.id ?? null,
317	      })
318	      .eq("id", requisicaoId);
319	
320	    setConcluindo(false);
321	    onConcluida?.();
322	    onClose();
323	  };
324	
325	  const finalizarEDarEntrada = () => {
326	    // Se há itens sem conferência, pedir confirmação antes de finalizar parcialmente
327	    if (stats.conferidos < stats.totalItens) {
328	      setConfirmandoFinalizar(true);
329	      return;
330	    }
331	    void executarFinalizacao();
332	  };
333	
334	  const stats = useMemo(() => {
335	    const totalItens = localItems.length;
336	    const conferidos = localItems.filter((i) => (Number(i.quantidade_recebida || "0") || 0) > 0).length;
337	    const totalSolicitado = localItems.reduce((acc, i) => acc + (i.quantidade_solicitada || 0), 0);
338	    const totalRecebido = localItems.reduce((acc, i) => acc + (Number(i.quantidade_recebida || "0") || 0), 0);
339	    const caixasBipadas = bipsLog.length;
340	    const allConferidos = totalItens > 0 && conferidos === totalItens;
341	    return { totalItens, conferidos, totalSolicitado, totalRecebido, caixasBipadas, allConferidos };
342	  }, [localItems, bipsLog]);
343	
344	  return (
345	    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
346	      <DialogContent
347	        data-mia-modal="conferir-chegada-requisicao-nome"
348	        className="max-w-[100vw] sm:max-w-[98vw] w-full h-[100dvh] sm:h-[95vh] p-0 flex flex-col overflow-hidden bg-white dark:bg-[#0A0A0A] sm:rounded-[1.5rem] rounded-none"
349	      >
350	        {/* Header */}
351	        <div className="flex items-center justify-between gap-2 px-3 sm:px-5 py-2 sm:py-3 flex-shrink-0 border-b border-[#57715B]/10">
352	          <div className="flex items-center gap-2 sm:gap-3 min-w-0 flex-1">
353	            <Button
354	              data-mia-action="close"
355	              variant="ghost"
356	              size="icon"
357	              onClick={onClose}
358	              className="rounded-2xl hover:bg-[#57715B]/10 h-11 w-11 flex-shrink-0"
359	            >
360	              <ArrowLeft className="w-5 h-5 text-[#57715B]" />
361	            </Button>
362	            <div className="h-10 w-10 rounded-2xl bg-[#57715B]/10 flex items-center justify-center flex-shrink-0">
363	              <ScanBarcode className="h-5 w-5 text-[#57715B]" />
364	            </div>
365	            <div className="min-w-0 flex-1">
366	              <DialogTitle className="text-base sm:text-lg font-bold text-[#57715B] dark:text-[#8FAE94] truncate">
367	                Conferir chegada · {requisicaoNome}
368	              </DialogTitle>
369	              <p className="text-[11px] sm:text-xs text-muted-foreground flex items-center gap-1 truncate">
370	                <MapPin className="w-3 h-3 flex-shrink-0" /> <span className="truncate">{lojaDestinoNome}</span>
371	              </p>
372	            </div>
373	          </div>
374	          <div className="flex p-1 rounded-xl bg-white/60 dark:bg-zinc-800 border border-white/20 dark:border-white/10 flex-shrink-0">
375	            <button
376	              onClick={() => scanner.setScanMode("bluetooth")}
377	              aria-label="Scanner Bluetooth"
378	              className={cn(
379	                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
380	                scanner.scanMode === "bluetooth"
381	                  ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm"
382	                  : "text-muted-foreground hover:text-foreground",
383	              )}
384	            >
385	              <Bluetooth className="h-4 w-4" /> <span className="hidden sm:inline">Scanner</span>
386	            </button>
387	            <button
388	              onClick={() => scanner.setScanMode("camera")}
389	              aria-label="Scanner por câmera"
390	              className={cn(
391	                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
392	                scanner.scanMode === "camera"
393	                  ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm"
394	                  : "text-muted-foreground hover:text-foreground",
395	              )}
396	            >
397	              <Camera className="h-4 w-4" /> <span className="hidden sm:inline">Câmera</span>
398	            </button>
399	          </div>
400	        </div>
401	
402	        {/* Stats */}
403	        <div className="px-3 sm:px-5 py-3 flex-shrink-0 border-b border-[#57715B]/10 grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-3">
404	          <Stat label="Itens conferidos" value={`${stats.conferidos}/${stats.totalItens}`} />
405	          <Stat label="Caixas bipadas" value={String(stats.caixasBipadas)} icon={<Boxes className="w-3 h-3" />} />
406	          <Stat label="Un. recebidas" value={`${stats.totalRecebido}/${stats.totalSolicitado}`} />
407	          <Stat label="Bips" value={String(stats.caixasBipadas)} />
408	        </div>
409	
410	        {/* Scanner input invisível */}
411	        {scanner.scanMode === "bluetooth" && <input {...scanner.inputProps} />}
412	
413	        {/* Body */}
414	        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
415	          {scanner.scanMode === "camera" ? (
416	            <div className="w-full md:w-[260px] flex-shrink-0 border-b md:border-b-0 md:border-r border-[#57715B]/10 bg-black overflow-hidden relative">
417	              <div id={scanner.cameraElementId} className="w-full h-[200px] md:h-full" />
418	              <CameraScannerStatus
419	                starting={scanner.cameraStarting}
420	                error={scanner.cameraError}
421	                onRetry={scanner.retryCamera}
422	              />
423	            </div>
424	          ) : (
425	            <div
426	              className="w-full md:w-[200px] flex-shrink-0 border-b md:border-b-0 md:border-r border-[#57715B]/10 flex flex-col items-center justify-center p-5 cursor-pointer"
427	              onClick={() => document.querySelector<HTMLInputElement>("input[autofocus]")?.focus()}
428	            >
