430	                <Bluetooth className="w-9 h-9 text-[#57715B]" />
431	                <div
432	                  className="absolute inset-0 rounded-full border-[3px] border-[#57715B]/20 border-t-[#57715B] animate-spin"
433	                  style={{ animationDuration: "3s" }}
434	                />
435	              </div>
436	              <h3 className="text-sm font-bold text-[#57715B] dark:text-[#8FAE94] mt-4">Aguardando bip…</h3>
437	              <p className="text-[11px] text-muted-foreground text-center mt-1">
438	                Sem etiqueta? Marque manual no item.
439	              </p>
440	            </div>
441	          )}
442	
443	          {/* Lista de itens da requisição */}
444	          <div className="flex-1 flex flex-col overflow-hidden">
445	            <ScrollArea className="flex-1">
446	              <div className="p-2.5 space-y-2">
