463	        <div
464	          className="px-3 sm:px-5 py-3 border-t border-[#57715B]/10 flex items-center justify-between gap-2 flex-shrink-0"
465	          style={{ paddingBottom: "calc(env(safe-area-inset-bottom) + 12px)" }}
