571	                  />
572	                </div>
573	                <p className="text-xs text-amber-700 bg-amber-50 dark:bg-amber-900/20 rounded-md p-2">
574	                  Marcar manual NÃO gera movimentação de estoque automática (sem etiqueta = sem
575	                  rastreabilidade).
576	                </p>
577	              </div>
578	            </AlertDialogDescription>
579	          </AlertDialogHeader>
580	          <AlertDialogFooter>
581	            <AlertDialogCancel
582	              onClick={() => setManual((s) => ({ ...s, open: false }))}
583	              className="border-[#57715B]/20 hover:bg-[#57715B]/10"
584	            >
585	              Cancelar
586	            </AlertDialogCancel>
587	            <AlertDialogAction
588	              onClick={() => void confirmManual()}
589	              className="bg-[#57715B] hover:bg-[#465b49] text-white"
590	            >
591	              Confirmar
592	            </AlertDialogAction>
593	          </AlertDialogFooter>
594	        </AlertDialogContent>
595	      </AlertDialog>
596	    </Dialog>
597	  );
598	}
