                    />

                    <Route
                      path="/mia"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <MiaInlineChat />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />

                    <Route
                      path="/mia/outcomes"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <MiaOutcomesDashboard />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    <Route
                      path="/mia/health"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <MiaHealthDashboard />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    <Route
                      path="/mia/patterns"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <MiaPatternsDashboard />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    <Route
                      path="/mia/improve"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <MiaImproveDashboard />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    <Route
                      path="/mia/observability"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <MiaObservabilityDashboard />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    <Route path="*" element={<NotFound />} />

                  </Routes>
                  </MiaProvider>
                </StoreProvider>
              </PermissionsProvider>
            </AuthProvider>
          </BrowserRouter>
        </TooltipProvider>
      </ThemeProvider>
    </QueryClientProvider>
  );
};

export default App;

