import React, { createContext, useContext, useState, useEffect, ReactNode, useRef } from 'react';
import { useAuth } from '@/shared/hooks/useAuth';
import { usePermissions } from '@/shared/hooks/usePermissions';
import { supabase } from '@/integrations/supabase/client';
import { wideInfo, wideDebug, wideWarn, wideError } from '@/shared/lib/telemetry/wide-events';
import { recordStoreChange, recordStoreChangeDuration } from '@/shared/lib/telemetry/metrics';
import { recordRumStoreChange } from '@/shared/lib/telemetry/rum';
import { handleError } from '@/shared/lib/error-handler';

interface Store {
  id: number;
  name: string;
  address: string;
  shortName: string;
  tipo?: string; // 'Loja' | 'Fabrica' (do banco) - opcional para fallback
}

interface StoreContextType {
  selectedStore: Store | null;
  setSelectedStore: (store: Store) => void;
  // Forçar seleção programática (ignora permissões) - útil para páginas exclusivas da Fábrica
  forceSetSelectedStore: (predicate: (s: Store) => boolean) => void;
  stores: Store[];
  loading: boolean;
  canChangeStore: boolean;
}

// Lista predefinida de lojas (fallback caso não consiga carregar do banco)
// IDs atualizados conforme migration 20260303120000_reorganize_store_ids_add_brasilia_shopping
const STORES: Store[] = [
  { id: 1, name: 'Fábrica', address: 'Brasília - DF', shortName: 'Fábrica', tipo: 'Fabrica' },
  { id: 2, name: 'Momma Asa Sul', address: 'Brasília - DF', shortName: 'Asa Sul', tipo: 'Loja' },
  { id: 3, name: 'Momma Asa Norte', address: 'Asa Norte, Brasília - DF', shortName: 'Asa Norte', tipo: 'Loja' },
  { id: 4, name: 'Momma Lago Sul', address: 'Brasília - DF, Lago Sul', shortName: 'Lago Sul', tipo: 'Loja' },
  { id: 5, name: 'Momma Águas Claras', address: 'Águas Claras, Brasília - DF', shortName: 'Águas Claras', tipo: 'Loja' },
  { id: 6, name: 'Momma Brasília Shopping', address: 'Brasília Shopping, Brasília - DF', shortName: 'Brasília Shopping', tipo: 'Loja' }
];

// NOTA: Todos os dados existentes (produtos, movimentações, etc.)
// pertencem à loja Asa Sul. As lojas Lago Sul e Asa Norte
// ainda não possuem dados ou movimentações.

const StoreContext = createContext<StoreContextType | undefined>(undefined);

interface StoreProviderProps {
  children: ReactNode;
}

export const StoreProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { user, userProfile } = useAuth();
  const { isAdmin, canSwitchStore } = usePermissions();
  const [selectedStore, setSelectedStoreState] = useState<Store | null>(null);
  const [loading, setLoading] = useState(true);
  const [canChangeStore, setCanChangeStore] = useState(false);
  const [availableStores, setAvailableStores] = useState<Store[]>(STORES);

  // Carregar lojas do banco de dados
  const loadStoresFromDB = async () => {
    wideDebug('store.load_stores_start', 'Iniciando carregamento de lojas do banco', {
      attributes: { 'store.source': 'supabase' },
    });
    try {
      const { data, error } = await supabase
        .from('lojas')
        .select('id, nome, endereco, tipo')
        .eq('ativo', true)
        .order('nome');

      if (error) {
        wideError('store.load_stores_error', 'Erro ao carregar lojas do Supabase', {
          attributes: {
            'store.error_code': error.code,
            'store.error_message': error.message,
          },
        });
        throw error;
      }

      const storeCount = data?.length || 0;
      const formattedStores = data?.map(store => {
        // Gerar shortName baseado no nome da loja
        let shortName = store.nome;
        if (store.nome.startsWith('Momma ')) {
          shortName = store.nome.replace('Momma ', '');
        }
        if (store.nome.toLowerCase().includes('fábrica') || store.tipo === 'Fabrica') {
          shortName = 'Fábrica';
        }

        return {
          id: store.id,
          name: store.nome,
          address: store.endereco,
          shortName: shortName,
          tipo: store.tipo
        };
      }) || STORES;

      wideDebug('store.load_stores_success', `Lojas carregadas: ${storeCount}`, {
        attributes: {
          'store.count': storeCount,
          'store.source': 'supabase',
        },
      });
      setAvailableStores(formattedStores);
      return formattedStores;
    } catch (error) {
      handleError(error, { domain: 'store', operation: 'loadStoresFromDB', showToast: false });
      wideDebug('store.load_stores_fallback', 'Usando lojas predefinidas como fallback', {
        attributes: { 'store.fallback_count': STORES.length },
      });
      return STORES; // Fallback para lojas predefinidas
    }
  };

  // Carregar loja selecionada do localStorage ou perfil do usuário
  const loadSelectedStore = (stores: Store[]): Store | null => {
    wideDebug('store.select_start', 'Iniciando seleção de loja', {
      attributes: {
        'store.has_user_profile': !!userProfile,
        'store.can_change_store': userProfile?.can_change_store ?? false,
        'store.default_store_id': userProfile?.default_store_id ?? 0,
        'store.available_count': stores.length,
        'store.is_admin': isAdmin(),
      },
    });

    // Para usuários que NÃO podem alterar loja (não-admin), sempre usar default_store_id
    if (!canSwitchStore() && !userProfile?.can_change_store) {
      if (userProfile?.default_store_id) {
        const userStore = stores.find(s => s.id === userProfile.default_store_id);
        if (userStore) {
          localStorage.setItem('selectedStore', JSON.stringify(userStore));
          return userStore;
        }
      }
      // Fallback: Tentar recuperar do localStorage se o perfil ainda não carregou (estado transiente)
      // Isso evita que o usuário "caia" na Fábrica enquanto o perfil carrega
      if (!userProfile) {
        try {
          const saved = localStorage.getItem('selectedStore');
          if (saved) {
            const parsed = JSON.parse(saved);
            const store = stores.find(s => s.id === parsed.id);
            if (store) {
              wideDebug('store.select_cache', 'Sem perfil: usando cache local temporário', {
                attributes: { 'store.name': store.name, 'store.id': store.id },
              });
              return store;
            }
          }
        } catch (e) {
          handleError(e, { domain: 'store', operation: 'loadSelectedStore.localStorageFallback', showToast: false });
        }
      }

      // Fallback imediato: selecionar Fábrica quando perfil ainda não carregou ou loja padrão inválida
      const fabrica = stores.find(s => s.shortName === 'Fábrica' || s.name.toLowerCase().includes('fábrica'));
      if (fabrica) {
        localStorage.setItem('selectedStore', JSON.stringify(fabrica));
        return fabrica;
      }
      return null;
    }

    // Para admins/operações gerais ou usuários com permissão de alterar loja: usar localStorage primeiro
    if (canSwitchStore() || userProfile?.can_change_store) {
      // PRIORIDADE 1: Tentar carregar do localStorage primeiro (preservar contexto)
      try {
        const saved = localStorage.getItem('selectedStore');
        if (saved) {
          const parsed = JSON.parse(saved);
          const store = stores.find(s => s.id === parsed.id);
          if (store) {
            wideDebug('store.select_localStorage', 'Loja preservada do localStorage', {
              attributes: { 'store.name': store.name, 'store.id': store.id },
            });
            return store;
          } else {
            wideWarn('store.select_localStorage_invalid', 'Loja do localStorage não encontrada nas lojas disponíveis', {
              attributes: { 'store.invalid_id': parsed.id },
            });
            // Limpar localStorage inválido
            localStorage.removeItem('selectedStore');
          }
        }
      } catch (error) {
        handleError(error, { domain: 'store', operation: 'loadSelectedStore.localStorage', showToast: false });
        // Limpar localStorage corrompido
        localStorage.removeItem('selectedStore');
      }

      // PRIORIDADE 2: Se não há localStorage válido, usar loja padrão do perfil
      if (userProfile?.default_store_id) {
        const userStore = stores.find(s => s.id === userProfile.default_store_id);
        if (userStore) {
          wideDebug('store.select_profile_default', 'Usando loja padrão do perfil', {
            attributes: { 'store.name': userStore.name, 'store.id': userStore.id },
          });
          // Salvar no localStorage para preservar na próxima vez
          localStorage.setItem('selectedStore', JSON.stringify(userStore));
          return userStore;
        } else {
          wideWarn('store.select_profile_invalid', 'Loja padrão do perfil não encontrada', {
            attributes: { 'store.default_store_id': userProfile.default_store_id },
          });
        }
      }

      // PRIORIDADE 3: Para admins sem loja padrão, usar a primeira loja como fallback
      // Isso só acontece para admins que não têm loja padrão configurada
      if (stores.length > 0) {
        const fallbackStore = stores[0];
        wideDebug('store.select_fallback', 'Admin sem loja padrão: usando fallback', {
          attributes: { 'store.name': fallbackStore.name, 'store.id': fallbackStore.id },
        });
        // Salvar no localStorage para preservar na próxima vez
        localStorage.setItem('selectedStore', JSON.stringify(fallbackStore));
        return fallbackStore;
      }
    }

    wideError('store.select_no_store', 'Nenhuma loja disponível ou usuário sem permissões adequadas', {
      attributes: {
        'store.available_count': stores.length,
        'store.has_user_profile': !!userProfile,
      },
    });
    return null;
  };

  // Salvar loja selecionada no localStorage (apenas para admins)
  const saveSelectedStore = (store: Store) => {
    if (canChangeStore) {
      try {
        localStorage.setItem('selectedStore', JSON.stringify(store));
      } catch (error) {
        handleError(error, { domain: 'store', operation: 'saveSelectedStore', showToast: false });
      }
    }
  };

  // Ref para medir duração do re-render após troca de unidade
  const storeChangeMarkRef = useRef<number | null>(null);

  const setSelectedStore = (store: Store) => {
    wideDebug('store.change_attempt', 'Tentativa de mudança de loja', {
      attributes: {
        'store.target_name': store.name,
        'store.target_id': store.id,
        'store.can_change': canChangeStore,
        'store.is_admin': isAdmin(),
      },
    });

    // Permitir mudança se o usuário pode alterar loja OU é administrador/operações gerais
    if (canChangeStore || canSwitchStore()) {
      // Telemetria: emitir wide event de troca de unidade
      const previousStore = selectedStore;
      if (previousStore && previousStore.id !== store.id) {
        wideInfo('store.change', `Troca de unidade: ${previousStore.name} → ${store.name}`, {
          attributes: {
            'store.from_id': previousStore.id,
            'store.from_name': previousStore.name,
            'store.to_id': store.id,
            'store.to_name': store.name,
          },
        });
        recordStoreChange({ 'store.to_name': store.name });
        recordRumStoreChange(store.name);

        // Marcar início para medir duração do re-render
        storeChangeMarkRef.current = performance.now();
      }

      setSelectedStoreState(store);
      saveSelectedStore(store);
    } else {
      wideWarn('store.change_blocked', 'Mudança de loja bloqueada — usuário sem permissão', {
        attributes: {
          'store.target_name': store.name,
          'store.target_id': store.id,
        },
      });
    }
  };

  // Forçar seleção de loja de forma programática (ignora permissões)
  const forceSetSelectedStore = (predicate: (s: Store) => boolean) => {
    try {
      const target = availableStores.find(predicate);
      if (target) {
        setSelectedStoreState(target);
        try {
          localStorage.setItem('selectedStore', JSON.stringify(target));
        } catch (e) {
          handleError(e, { domain: 'store', operation: 'forceSetSelectedStore.localStorage', showToast: false });
        }
      }
    } catch (e) {
      handleError(e, { domain: 'store', operation: 'forceSetSelectedStore', showToast: false });
    }
  };

  // MIA Glass-Box — escuta evento `mia:switch-store` e troca loja via context.
  // Usado quando StoreSelector não está visível na rota atual (mobile, modais).
  // Normaliza nome usando shortName, name e variações comuns.
  useEffect(() => {
    const handler = (e: Event) => {
      const detail = (e as CustomEvent<{ name: string }>).detail;
      const target = detail?.name?.toString().trim();
      if (!target) return;
      const norm = (s: string) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
      const t = norm(target);
      const found = availableStores.find(s =>
        norm(s.name) === t ||
        norm(s.shortName) === t ||
        norm(s.name).includes(t) ||
        norm(s.shortName).includes(t) ||
        t.includes(norm(s.shortName))
      );
      if (found) {
        setSelectedStore(found);
      } else {
        wideWarn('store.mia_switch_no_match', `MIA pediu trocar loja "${target}" mas não bateu`, {
          attributes: { 'mia.target': target, 'stores.available': availableStores.length },
        });
      }
    };
    window.addEventListener('mia:switch-store', handler);
    return () => window.removeEventListener('mia:switch-store', handler);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [availableStores, canChangeStore]);

  // Medir duração do re-render após troca de unidade
  useEffect(() => {
    if (storeChangeMarkRef.current !== null && selectedStore) {
      const durationMs = Math.round(performance.now() - storeChangeMarkRef.current);
      storeChangeMarkRef.current = null;

      const pageRoute = typeof window !== 'undefined' ? window.location.pathname : '';
      wideInfo('store.change.performance', `Re-render após troca de unidade: ${durationMs}ms`, {
        attributes: {
          'duration_ms': durationMs,
          'page.route': pageRoute,
        },
      });
      recordStoreChangeDuration(durationMs);
    }
  }, [selectedStore]);

  // Usar useRef para controlar inicialização sem causar re-renders
  const initializationRef = useRef<{
    isInitialized: boolean;
    currentUserId: string | null;
    isInitializing: boolean;
    lastUserProfileCheck: string | null;
    lastAdminStatus?: boolean;
    lastCanChangeStore?: boolean;
    profileLoaded?: boolean;
  }>({ isInitialized: false, currentUserId: null, isInitializing: false, lastUserProfileCheck: null });

  // Separar o useEffect para evitar loops
  useEffect(() => {
    wideDebug('store.context_reset_check', 'Verificando reset de contexto', {
      attributes: {
        'store.user_id': user?.id || '',
        'store.current_user_id': initializationRef.current.currentUserId || '',
      },
    });

    // Reset quando não há usuário
    if (!user) {
      wideDebug('store.context_reset', 'Resetando contexto — usuário deslogado', {
        attributes: { 'store.reason': 'no_user' },
      });
      setSelectedStoreState(null);
      setCanChangeStore(false);
      initializationRef.current = {
        isInitialized: false,
        currentUserId: null,
        isInitializing: false,
        lastUserProfileCheck: null,
        lastAdminStatus: undefined,
        lastCanChangeStore: undefined,
        profileLoaded: false
      };
      setLoading(false);
      return;
    }

    // Se mudou de usuário, resetar
    if (initializationRef.current.currentUserId && initializationRef.current.currentUserId !== user.id) {
      wideDebug('store.context_reset', 'Resetando contexto — usuário mudou', {
        attributes: {
          'store.previous_user_id': initializationRef.current.currentUserId || '',
          'store.new_user_id': user.id,
        },
      });
      initializationRef.current = {
        isInitialized: false,
        currentUserId: null,
        isInitializing: false,
        lastUserProfileCheck: null
      };
      setSelectedStoreState(null);
      setCanChangeStore(false);
    }
  }, [user?.id]); // Usar apenas user?.id como dependência

  // Extrai resultado de canSwitchStore para evitar chamada de função na deps array
  const isAdminUser = canSwitchStore();

  // UseEffect separado para inicialização quando userProfile estiver disponível
  useEffect(() => {
    wideDebug('store.init_check', 'Verificando inicialização de lojas', {
      attributes: {
        'store.has_user': !!user,
        'store.has_user_profile': !!userProfile,
        'store.is_initialized': initializationRef.current.isInitialized,
        'store.is_initializing': initializationRef.current.isInitializing,
      },
    });

    // Se o userProfile foi carregado depois da inicialização e o usuário é admin,
    // verificar se há uma loja no localStorage que deve ser preservada
    if (user && userProfile && initializationRef.current.isInitialized &&
      initializationRef.current.currentUserId === user.id && canSwitchStore()) {
      try {
        const saved = localStorage.getItem('selectedStore');
        if (saved && selectedStore) {
          const parsed = JSON.parse(saved);
          // Se a loja do localStorage é diferente da atual, atualizar
          if (parsed.id !== selectedStore.id) {
            const storeFromStorage = availableStores.find(s => s.id === parsed.id);
            if (storeFromStorage) {
              wideDebug('store.restore_from_storage', 'Admin: restaurando loja do localStorage após carregamento do userProfile', {
                attributes: { 'store.name': storeFromStorage.name, 'store.id': storeFromStorage.id },
              });
              setSelectedStoreState(storeFromStorage);
              return; // Sair cedo para evitar reinicialização
            }
          }
        }
      } catch (error) {
        handleError(error, { domain: 'store', operation: 'restoreFromStorage', showToast: false });
      }
    }

    // Timeout para evitar loading perpétuo quando userProfile não carrega
    let initTimeout: NodeJS.Timeout;

    const initializeStore = async (force: boolean = false) => {
      wideDebug('store.init_start', 'Iniciando inicialização de loja', {
        attributes: {
          'store.has_user': !!user,
          'store.has_user_profile': !!userProfile,
          'store.is_initialized': initializationRef.current.isInitialized,
          'store.is_initializing': initializationRef.current.isInitializing,
          'store.force': force,
        },
      });

      // Verificação básica - só precisa do user
      if (!user) {
        setLoading(false);
        return;
      }

      // Se userProfile existe, verificar se são do mesmo usuário
      if (userProfile && userProfile.user_id && user.id !== userProfile.user_id) {
        wideDebug('store.init_sync_wait', 'user.id !== userProfile.user_id — aguardando sincronização', {
          attributes: { 'store.user_id': user.id },
        });
        setLoading(false);
        return;
      }

      // Se userProfile é null/undefined e NÃO estamos forçando, AGUARDAR
      if (!userProfile && !force) {
        wideDebug('store.init_waiting_profile', 'userProfile ainda não disponível, aguardando', {
          attributes: { 'store.user_id': user.id },
        });
        // Manter loading=true enquanto aguarda
        setLoading(true);
        return;
      }

      // Se estamos aqui e userProfile é null, mas force=true, logar aviso
      if (!userProfile && force) {
        wideWarn('store.init_force_no_profile', 'Forçando inicialização sem userProfile (timeout atingido)', {
          attributes: { 'store.user_id': user.id },
        });
      }

      // Se já está inicializando, não fazer nada
      if (initializationRef.current.isInitializing) {
        return;
      }

      // Se já foi inicializado para este usuário, verificar se precisamos re-inicializar
      // EXCETO se for force=true (pode ser uma tentativa de recuperação)
      const profileNewlyAvailable = userProfile && !initializationRef.current.profileLoaded;

      if (initializationRef.current.isInitialized &&
        initializationRef.current.currentUserId === user.id &&
        !force &&
        !profileNewlyAvailable) {
        return;
      }

      wideDebug('store.init_begin', `Iniciando inicialização (Re-init: ${profileNewlyAvailable ? 'Sim (Profile chegou)' : 'Não'})`, {
        attributes: {
          'store.re_init': !!profileNewlyAvailable,
          'store.user_id': user.id,
        },
      });
      initializationRef.current.isInitializing = true;
      setLoading(true);

      try {
        // Determinar se o usuário pode alterar loja
        // Administradores SEMPRE podem alterar loja, outros usuários dependem do can_change_store
        const isUserAdmin = canSwitchStore();
        const userCanChangeStore = isUserAdmin || (userProfile?.can_change_store ?? false);

        // FORÇA ADMIN/OPERAÇÕES GERAIS: pode sempre alterar loja
        const finalCanChangeStore = userCanChangeStore;

        wideDebug('store.init_permissions', 'Permissões de loja calculadas', {
          attributes: {
            'store.can_change': finalCanChangeStore,
            'store.is_admin': isUserAdmin,
            'store.profile_can_change': userProfile?.can_change_store ?? false,
          },
        });
        setCanChangeStore(finalCanChangeStore);

        // Carregar lojas disponíveis
        const stores = await loadStoresFromDB();

        // Carregar loja selecionada
        const store = loadSelectedStore(stores);
        setSelectedStoreState(store);

        // Marcar como inicializado para este usuário
        initializationRef.current = {
          isInitialized: true,
          currentUserId: user.id,
          isInitializing: false,
          lastUserProfileCheck: user.id,
          lastAdminStatus: canSwitchStore(),
          lastCanChangeStore: userProfile?.can_change_store,
          profileLoaded: !!userProfile // NOVA FLAG
        };

        wideInfo('store.init_complete', 'Inicialização de lojas completa', {
          attributes: {
            'store.selected_name': store?.name || 'nenhuma',
            'store.selected_id': store?.id ?? 0,
            'store.available_count': stores.length,
          },
        });
      } catch (error) {
        handleError(error, { domain: 'store', operation: 'initializeStore', showToast: false });
        initializationRef.current.isInitializing = false;
      } finally {
        setLoading(false);
      }
    };

    // Executar se temos user
    if (user) {
      // Se as permissões mudaram, forçar reinicialização
      const currentAdminStatus = canSwitchStore();
      const currentCanChangeStore = userProfile?.can_change_store;
      if (initializationRef.current.isInitialized &&
        (initializationRef.current.lastAdminStatus !== currentAdminStatus ||
          initializationRef.current.lastCanChangeStore !== currentCanChangeStore)) {

        // Se o usuário perdeu a permissão de admin ou de alterar loja, limpar localStorage
        const lostAdminPermission = initializationRef.current.lastAdminStatus === true && currentAdminStatus === false;
        const lostChangeStorePermission = initializationRef.current.lastCanChangeStore === true && currentCanChangeStore === false;

        if (lostAdminPermission || lostChangeStorePermission) {
          localStorage.removeItem('selectedStore');
        }

        initializationRef.current.isInitialized = false;
        initializationRef.current.isInitializing = false;
      }

      // Se já está inicializado e as permissões não mudaram, mas agora temos userProfile (e antes talvez não tivéssemos)
      // podemos querer re-avaliar

      // Configurar timeout para forçar inicialização mesmo sem userProfile
      initTimeout = setTimeout(() => {
        wideWarn('store.init_timeout', 'Timeout atingido — forçando inicialização', {
          attributes: { 'store.user_id': user.id },
        });
        if (!initializationRef.current.isInitialized) {
          initializeStore(true);
        }
      }, 4000); // 4 segundos de timeout

      initializeStore(false);
    } else {
      // Se não temos user, definir loading como false
      setLoading(false);
    }

    // Cleanup do timeout
    return () => {
      if (initTimeout) {
        clearTimeout(initTimeout);
      }
    };
  }, [user?.id, isAdminUser, userProfile]); // IMPORTANTE: userProfile e isAdminUser adicionados como dependência

  const value: StoreContextType = {
    selectedStore,
    setSelectedStore,
    forceSetSelectedStore,
    stores: availableStores,
    loading,
    canChangeStore,
  };

  return (
    <StoreContext.Provider value={value}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = (): StoreContextType => {
  const context = useContext(StoreContext);
  if (!context) {
    throw new Error('useStore must be used within a StoreProvider');
  }
  return context;
};

