/**
 * @module MommaPageLayout
 *
 * Layout decorativo de página com identidade visual Momma.
 * Inclui faixa de toldo na parte superior, folhas animadas no fundo
 * e brilhos ambientes sutis.
 */

import React from 'react';
import { Leaf, Sun, Moon, Sparkles } from 'lucide-react'; // Added Sparkles here just in case, though unrelated to layout background directly
import { cn } from '@/shared/lib/utils';
import { useTheme } from 'next-themes';
import { Button } from '@/shared/ui/button';

interface MommaPageLayoutProps {
  children: React.ReactNode;
  className?: string;
  showAwning?: boolean;
  pageTitle?: string; // Optional: for pages that want a consistent title header
}

/**
 * Layout de página com elementos decorativos da marca Momma.
 * Renderiza faixa de toldo, folhas animadas e brilhos ambientes como fundo.
 *
 * @param children - Conteúdo principal da página.
 * @param className - Classes CSS adicionais para o container de conteúdo.
 * @param showAwning - Se exibe a faixa de toldo no topo (padrão: `true`).
 * @param pageTitle - Título opcional da página (reservado para uso futuro).
 */

